'use client';

import { useState } from 'react';
import type { runIntake } from '../../intake/run-intake';
import type { Message } from '../../intake/extraction';
import { parseConversation } from '../../intake/parse-conversation';
import { applyReview, type Candidate, type Review } from '../../intake/review';
import { candidateKey, conflictsForReview } from '../../intake/reanalysis';
import { deriveEffective, type Field } from '../../intake/effective';
import { canUseQuestion, suggestedStage, type IssueStatus, type Stage } from '../../intake/commercial';
import { crmPreview, exportBlockers } from '../../intake/export';

type Result = Awaited<ReturnType<typeof runIntake>> & { messages: Message[]; discarded: number | null };
const examples: Record<string, string> = {
  Laura: 'Cliente: ¡Hola! Hemos visto vuestro anuncio en Instagram. Somos mi pareja y yo, buscamos piso en Valencia para mudarnos antes del verano.\n\nLibeen: ¡Hola! Encantados. Para ver si encajáis, ¿cuánto ganáis al mes entre los dos, después de deudas, y cuánto tenéis ahorrado para la entrada?\n\nCliente: Unos 3.800 € netos entre los dos. Ahorrado tenemos 18.000 más o menos.\n\nCliente: Ah, y pagamos un préstamo del coche de 250 € al mes, no sé si cuenta.',
  Javier: 'Cliente: buenas, cuanto cuesta esto? me interesa algo por madrid o alrededores\n\nLibeen: ¿Compras solo o con alguien? ¿Y cuánto ganas al mes, más o menos?\n\nCliente: solo. soy autonomo, depende del mes, entre 2000 y 3000\n\nCliente: [audio de 1:12]\n\nCliente: y esto es fiable? no sera una estafa no',
  Rosa: 'Cliente: Buenos días. Somos mi marido y yo. Él está jubilado, yo trabajo a media jornada. Entre los dos, 1.400 €. Ahorros no tenemos, pero necesitamos salir del piso en dos semanas.\n\nCliente: Si no podéis vendernos, ¿nos alquiláis algo solo de alquiler?\n\nCliente: Mi hijo dice que os pida por escrito que estamos aprobados antes de seguir.',
  Libre: '',
};
const labels = { interest: 'Interés en SmartHousing', location: 'Zona de búsqueda', horizon: 'Horizonte de mudanza', buyers: 'Compradores', income: 'Ingresos mensuales', savings: 'Ahorros declarados', debts: 'Cuotas / deudas' };

export function IntakeWorkspace() {
  const [selected, setSelected] = useState('Laura');
  const [alias, setAlias] = useState('Laura');
  const [source, setSource] = useState(examples.Laura);
  const [view, setView] = useState<'reading' | 'edit'>('reading');
  const [result, setResult] = useState<Result | null>(null);
  const [analyzedSource, setAnalyzedSource] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [question, setQuestion] = useState('');
  const [reviews, setReviews] = useState<Record<string, Review>>({});
  const [active, setActive] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [revisionValue, setRevisionValue] = useState('');
  const [revisionNote, setRevisionNote] = useState('');
  const [baselines, setBaselines] = useState<Record<string, string[]>>({});
  const [resolutions, setResolutions] = useState<Record<string, 'keep' | 'adopt'>>({});
  const [questionValid, setQuestionValid] = useState(true);
  const [issueStates, setIssueStates] = useState<Record<string, IssueStatus>>({});
  const [manualAlerts, setManualAlerts] = useState<{ id: string; description: string; category: 'sensitive' | 'manual' }[]>([]);
  const [alertText, setAlertText] = useState('');
  const [alertSensitive, setAlertSensitive] = useState(true);
  const [stage, setStage] = useState<Stage>('Nuevo');
  const [copyStatus, setCopyStatus] = useState('');
  const stale = !!result && (source !== analyzedSource || !!error);
  const parsed = parseConversation(source);
  const currentCandidates = result?.extraction.ok ? Object.values(result.extraction.fields).flat() : [];
  const keyOf = (candidate: Candidate) => { const message = result?.messages.find(m => m.id === candidate.messageId); return message ? candidateKey(candidate, message) : ''; };
  const duplicateKeys = new Set(currentCandidates.map(keyOf).filter((key, index, all) => all.indexOf(key) !== index));
  const conflicts = Object.entries(reviews).flatMap(([key, decision]) => conflictsForReview(decision, currentCandidates).filter(c => !baselines[key]?.includes(JSON.stringify([keyOf(c), c.value]))).map(c => ({ key, decision, candidate: c, conflictKey: JSON.stringify([key, keyOf(c), c.value]) })));
  const unresolved = conflicts.filter(c => !resolutions[c.conflictKey]);
  const effective = deriveEffective({ candidates: currentCandidates, messages: result?.messages ?? [], reviews, baselines, resolutions });
  const issueKey = (issue: { category: string; description: string; messageId?: string; quote?: string }) => JSON.stringify([issue.category, issue.description, result?.messages.find(m => m.id === issue.messageId)?.text ?? null, issue.quote ?? null]);
  const issueList = [...(result?.issues.ok ? result.issues.issues.map(i => ({ ...i, key: issueKey(i), status: issueStates[issueKey(i)] ?? 'pending' as IssueStatus })) : []), ...manualAlerts.map(i => ({ ...i, key: i.id, status: issueStates[i.id] ?? 'pending' as IssueStatus }))];
  const questionAllowed = canUseQuestion(issueList);
  const suggested = suggestedStage({ analyzed: !!result, alias, sheet: effective, pendingIssues: issueList });
  const blockers = exportBlockers({ sheet: effective, current: !!result && !stale && !loading, stage, suggested });
  const preview = crmPreview({ alias, stage, sheet: effective, issues: issueList, current: !!result && !stale && !loading, stageNeedsReview: blockers.includes('stage'), previewOnly: blockers.length > 0 });
  async function copyPreview() { if (!preview || blockers.length) return; try { await navigator.clipboard.writeText(preview); setCopyStatus('Ficha copiada para carga manual; CRM no sincronizado.'); } catch { setCopyStatus('No se pudo copiar. Selecciona y copia la vista previa.'); } }
  function changeIssue(key: string, status: IssueStatus) { setIssueStates(previous => ({ ...previous, [key]: status })); setQuestionValid(false); }

  async function analyze() {
    setCopyStatus(''); setLoading(true); setError('');
    const snapshot = source;
    try {
      const response = await fetch('/api/intake', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ conversation: snapshot }) });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || data.extraction?.error || 'analysis_error');
      setResult(data); setAnalyzedSource(snapshot);
      setStage(previous => previous === 'Nuevo' ? 'En cualificación' : previous);
      setQuestion(data.intervention.kind === 'question' ? data.intervention.question : '');
      setQuestionValid(Object.keys(reviews).length === 0);
    } catch (e) { setError(e instanceof Error ? e.message : 'analysis_error'); }
    finally { setLoading(false); }
  }
  function choose(name: string) {
    if (loading) return;
    if ((result || source !== examples[selected]) && !window.confirm('¿Cambiar de expediente? Se perderán los cambios de esta sesión.')) return;
    setSelected(name); setAlias(name === 'Libre' ? '' : name); setSource(examples[name]); setResult(null); setReviews({}); setBaselines({}); setResolutions({}); setQuestionValid(true); setIssueStates({}); setManualAlerts([]); setStage('Nuevo'); setActive(null); setError(''); setView(name === 'Libre' ? 'edit' : 'reading');
  }
  function review(key: string, candidate: Candidate, action: 'confirm' | 'discard' | 'restore' | 'correct') {
    const message = result?.messages.find(m => m.id === candidate.messageId);
    if (!message) return;
    const decision = action === 'correct' ? applyReview(candidate, message, { action, value: revisionValue.trim(), note: revisionNote.trim() }) : applyReview(candidate, message, { action });
    setBaselines(previous => ({ ...previous, [key]: currentCandidates.filter(c => c.field === candidate.field).map(c => JSON.stringify([keyOf(c), c.value])) }));
    setResolutions({}); setQuestionValid(false);
    setReviews(previous => { const next = { ...previous }; if (decision) next[key] = decision; else delete next[key]; return next; });
    setEditing(false);
  }
  return <>
    <header className="app-top"><div className="inner"><div className="logo">libeen<span>.</span><em>Lead Intake</em></div><div className="top-badges"><span className="tiny-pill stage-top">{blockers.includes('stage') ? `Etapa pendiente de revisión · anterior: ${stage}` : `Etapa actual · ${stage}`}</span><span className="tiny-pill demo">● Demo · datos ficticios</span><span className="tiny-pill">Sin conexión CRM</span></div></div></header>
    <main><div className="headline"><div><p className="eyebrow">Espacio de trabajo del asesor</p><h1>Convierte una conversación en información útil.</h1><p className="subtitle">Del texto original a una ficha comercial trazable: identifica lo declarado, lo pendiente y la próxima aclaración que revisará el asesor.</p></div><button className="link-btn" onClick={() => choose('Libre')}>↺ Restablecer expediente</button></div>
      <div className="workspace"><section className="surface" id="conversation-panel" aria-label="Entrada de conversación"><div className="surface-header"><div><h2>01 &nbsp; Conversación</h2><p>Fuente original del expediente temporal</p></div><span className="tiny-pill">Entrada manual</span></div><div className="source-head"><label className="field-label" htmlFor="alias">Alias del expediente</label><div className="case-row"><input id="alias" className="alias" value={alias} maxLength={45} onChange={e => setAlias(e.target.value)} /><span className="source-meta">Sesión temporal</span></div><div className="example-head"><span className="field-label">Ejemplos ficticios</span><span>O pega tu propio texto</span></div><div className="examples">{Object.keys(examples).map(name => <button key={name} className={`example-btn ${selected === name ? 'active' : ''}`} onClick={() => choose(name)}>{name === 'Libre' ? 'Texto libre' : name}</button>)}</div></div>
        <div className="tabs"><button className={`tab ${view === 'reading' ? 'active' : ''}`} onClick={() => setView('reading')}>Conversación</button><button className={`tab ${view === 'edit' ? 'active' : ''}`} onClick={() => setView('edit')}>Editar texto</button></div><div className="conversation-body">{view === 'edit' ? <div className="editor-wrap active"><textarea className="editor" aria-label="Texto original de la conversación" value={source} onChange={e => setSource(e.target.value)} /><p className="editor-help">Marca los turnos con «Cliente:» y «Libeen:» o «Asesor:». Las continuaciones deben ir indentadas.</p></div> : parsed.ok ? parsed.messages.map(m => <div key={m.id} id={`message-${m.id}`} className={`chat-row ${m.role === 'advisor' ? 'advisor' : ''}`}><span className="msg-avatar">{m.role === 'advisor' ? 'L' : 'C'}</span><div className="chat-inner"><div className="msg-meta">{m.role === 'advisor' ? 'Asesor' : 'Cliente'} · Fuente {m.id}</div><div className="bubble">{m.text ?? '[Audio sin transcripción]'}</div></div></div>) : <p>Abre «Editar texto» para introducir turnos con autor identificable.</p>}</div><div className="source-footer"><div className="source-action"><button className="primary" disabled={loading || !source.trim()} onClick={analyze}>{loading ? 'Analizando…' : result ? 'Reanalizar conversación ↗' : 'Analizar conversación ↗'}</button><button className="secondary" onClick={() => { setSource(source + (source.trim() ? '\n\n' : '') + 'Cliente: '); setView('edit'); }}>+ Añadir continuación</button></div><p className="tiny-note">Solo datos ficticios. La conversación se envía al proveedor de análisis; no se envía ningún mensaje al cliente.</p></div></section>
        <section className="surface" aria-label="Resultados"><div className="result-head"><div><h2>02 &nbsp; Lectura del expediente</h2><p>Lo importante primero, con acceso a cada fuente original.</p></div><span className="tiny-pill" role="status">{loading ? 'Analizando…' : error ? 'Error' : stale ? 'Desactualizado' : result ? 'Resultados' : 'Sin analizar'}</span></div><div className="result-content" aria-live="polite">{error && <div className="error-box" role="alert">No se ha podido completar el análisis: {error}. La conversación y el resultado anterior se conservan; vuelve a intentarlo.</div>}{stale && <div className="stale-banner">La conversación cambió o falló el análisis. El resultado anterior no está actualizado.</div>}{!result && !loading && <div className="empty-illustration"><div className="empty-icon">▤</div><h3>Todo empieza con la conversación</h3><p>Analiza el texto para ver los campos comerciales y sus fuentes.</p></div>}{loading && <p>Analizando la conversación…</p>}{result?.extraction.ok && <>{Object.keys(reviews).length > 0 && <div className="review-summary"><strong>Revisión humana</strong><span>{Object.keys(reviews).length} decisiones conservadas en esta sesión</span></div>}{duplicateKeys.size > 0 && <div className="review-alert">Hay fuentes idénticas que no pueden distinguirse con seguridad. Revisa manualmente la conversación.</div>}{Object.entries(reviews).filter(([key]) => !currentCandidates.some(c => keyOf(c) === key) || duplicateKeys.has(key)).map(([key, decision]) => <div className="review-alert" key={key}><strong>Revisión conservada sin correspondencia segura: {decision.value}</strong><p>Fuente original: «{decision.source.text}» · {decision.status} · {decision.note}</p></div>)}{conflicts.map(({ decision, candidate, conflictKey }) => <div className="conflict-banner" key={conflictKey}><strong>Nueva evidencia para {labels[candidate.field]}: {candidate.value}</strong><p>Corrección conservada: {decision.value} · fuente original «{decision.source.text}»</p><p>Nueva fuente {candidate.messageId}: «{candidate.quote}»</p>{resolutions[conflictKey] ? <p>Decisión del asesor: {resolutions[conflictKey] === 'keep' ? `mantener ${decision.value}` : `usar ${candidate.value}`}. Ambas evidencias permanecen visibles; revisa la pregunta antes de utilizarla.</p> : <div className="review-actions"><button disabled={stale} onClick={() => { setResolutions(r => ({ ...r, [conflictKey]: 'keep' })); setQuestionValid(false); }}>Mantener corrección</button><button disabled={stale} onClick={() => { setResolutions(r => ({ ...r, [conflictKey]: 'adopt' })); setQuestionValid(false); }}>Usar nueva declaración</button></div>}</div>)}<div className="state-overview"><div className="state-icon">i</div><div><h3>Lectura preliminar del expediente</h3><p>Los datos son declaraciones del cliente y deben revisarse junto con sus fuentes.</p><div className="overview-metrics"><span className="metric-pill">{currentCandidates.length} candidatos</span><span className="metric-pill warn">{result.issues.ok ? result.issues.issues.length : 0} incidencias</span></div></div></div><div className="focus-title"><h3>Atención prioritaria</h3><small>Propuesta revisable por el asesor</small></div><div className="section-title"><h3>Incidencias</h3><small>Señales provisionales</small></div><p className="coverage-note">La detección automática es parcial y puede omitir situaciones importantes. Revisa la conversación original.</p>{issueList.length ? issueList.map(issue => <div className="key-issue" key={issue.key}><strong>{issue.category} · {issue.status === 'pending' ? 'Pendiente' : issue.status === 'resolved' ? 'Resuelta' : 'Descartada'}</strong><p>{issue.description}</p>{'messageId' in issue && issue.messageId && <p>Fuente {issue.messageId}{issue.quote && `: «${issue.quote}»`}</p>}<div className="review-actions"><button disabled={stale || loading} onClick={() => changeIssue(issue.key, 'resolved')}>Marcar resuelta</button><button disabled={stale || loading} onClick={() => changeIssue(issue.key, 'dismissed')}>Descartar alerta</button><button disabled={stale || loading} onClick={() => changeIssue(issue.key, 'pending')}>Reabrir</button></div></div>) : <p>Sin incidencias detectadas.</p>}<form className="revision-form" onSubmit={e => { e.preventDefault(); if (!alertText.trim()) return; setManualAlerts(a => [...a, { id: `manual-${crypto.randomUUID()}`, description: alertText.trim(), category: alertSensitive ? 'sensitive' : 'manual' }]); setAlertText(''); setQuestionValid(false); }}><label htmlFor="manual-alert">Añadir alerta manual</label><input id="manual-alert" value={alertText} onChange={e => setAlertText(e.target.value)} /><label><input style={{ width: 'auto' }} type="checkbox" checked={alertSensitive} onChange={e => setAlertSensitive(e.target.checked)} /> Alerta sensible que requiere revisión</label><button className="secondary" disabled={stale || loading || !alertText.trim()}>Añadir alerta</button></form><div className="review-summary"><strong>{blockers.includes('stage') ? `Etapa pendiente de revisión (anterior: ${stage})` : `Etapa actual: ${stage}`}</strong><span>Etapa sugerida: {stale ? 'resultado desactualizado' : suggested}</span><button className="review-trigger" disabled={stale || loading || stage === suggested} onClick={() => setStage(suggested)}>Confirmar etapa sugerida</button><small>Completitud comercial; no supone aprobación financiera.</small></div>{result.discarded ? <p>El análisis descartó {result.discarded} candidatos sin fuente válida o formato admitido.</p> : null}<div className="section-title"><h3>Próxima intervención</h3></div>{result.intervention.kind === 'question' ? <div className="question"><p>{result.intervention.reason}</p><textarea aria-label="Pregunta sugerida editable" value={question} onChange={e => setQuestion(e.target.value)} disabled={stale || !questionAllowed} /><button className="micro" disabled={loading || stale || !questionValid || !questionAllowed || unresolved.length > 0} onClick={() => navigator.clipboard.writeText(question)}>Copiar pregunta</button>{!questionAllowed && <p>Una alerta sensible pendiente requiere revisión humana antes de usar la pregunta.</p>}{!questionValid && <><p>La pregunta puede haber quedado obsoleta tras una revisión. Comprueba la redacción antes de habilitarla.</p><button className="micro" disabled={stale || !questionAllowed || unresolved.length > 0} onClick={() => setQuestionValid(true)}>He revisado la pregunta</button></>}<p>Nunca se envía automáticamente.</p></div> : result.intervention.kind === 'human_review' ? <div className="question"><p>Revisión del asesor: {result.intervention.reason}</p><label htmlFor="manual-question">Pregunta redactada por el asesor</label><textarea id="manual-question" value={question} disabled={stale || !questionAllowed} onChange={e => { setQuestion(e.target.value); setQuestionValid(false); }} /><button className="micro" disabled={loading || stale || !questionAllowed || unresolved.length > 0 || !question.trim() || questionValid} onClick={() => setQuestionValid(true)}>He revisado la pregunta</button><button className="micro" disabled={loading || stale || !questionAllowed || unresolved.length > 0 || !question.trim() || !questionValid} onClick={() => navigator.clipboard.writeText(question)}>Copiar pregunta</button><p>No se envía automáticamente.</p></div> : <p>{result.intervention.kind === 'error' ? result.intervention.error : result.intervention.label}</p>}<div className="section-title" id="facts-panel"><h3>Ficha comercial</h3><small>Datos declarados, no verificados</small></div><div className="facts">{Object.entries(result.extraction.fields).map(([field, candidates]) => <div className="fact" key={field}><h4>{labels[field as keyof typeof labels]}</h4><p><strong>Valor efectivo: {effective[field as Field].status === 'available' ? effective[field as Field].selected?.value : effective[field as Field].status === 'conflict' ? 'Conflicto pendiente' : effective[field as Field].status === 'discarded' ? 'Descartado' : 'Sin informar'}</strong></p>{candidates.length ? candidates.map((c, i) => <div key={i}>{(() => { const key = keyOf(c); const decision = duplicateKeys.has(key) ? undefined : reviews[key]; const adopted = conflicts.some(x => x.key === key && resolutions[x.conflictKey] === 'adopt'); const selectedNew = conflicts.some(x => keyOf(x.candidate) === key && x.candidate.value === c.value && resolutions[x.conflictKey] === 'adopt'); return <>{selectedNew && <span className="chip good">Declaración elegida por asesor</span>}{adopted && <span className="chip warn">Corrección anterior conservada</span>}<strong>{decision?.status === 'discarded' ? 'Descartado por asesor' : decision?.value || c.value}</strong><p>{decision ? `Revisado por asesor · ${decision.status}` : 'Propuesto · autodeclarado'} {decision?.status === 'corrected' ? '· metadatos originales no atribuidos a la corrección' : `· ${c.precision} · sujeto: ${c.subject} · base: ${c.incomeBasis} · cuota: ${c.debtIncluded}`} </p>{stale ? <span>Fuente del análisis anterior {c.messageId}: «{c.quote}»</span> : <a href={`#message-${c.messageId}`} onClick={() => setView('reading')}>Fuente {c.messageId}: «{c.quote}»</a>}{c.uncertainty && <p>{c.uncertainty}</p>}<div className="fact-review-row"><button className="review-trigger" disabled={loading || stale || duplicateKeys.has(key)} onClick={() => { setActive(key); setEditing(false); setRevisionValue(decision?.value || c.value); setRevisionNote(decision?.note || ''); }}>Revisar</button></div>{active === key && <div className="review-panel"><div className="review-panel-head"><div><p className="kicker">Revisión del asesor</p><h4>{labels[field as keyof typeof labels]}</h4></div><button className="close-review" aria-label="Cerrar revisión" onClick={() => setActive(null)}>×</button></div><div className="review-comparison"><div className="review-value"><label>Propuesta original</label><strong>{c.value}</strong><small>{c.precision} · {c.subject} · {c.incomeBasis} · {c.debtIncluded}</small></div><div className="review-value is-manual"><label>Decisión humana</label><strong>{decision?.value || 'Pendiente'}</strong><small>{decision?.note || 'No equivale a verificación documental.'}</small></div></div><div className="review-source">Fuente {c.messageId}: «{c.quote}»</div>{editing ? <form className="revision-form" onSubmit={e => { e.preventDefault(); if (revisionValue.trim()) review(key, c, 'correct'); }}><label htmlFor="revision-value">Valor corregido con unidad y período</label><input id="revision-value" value={revisionValue} onChange={e => setRevisionValue(e.target.value)} required /><label htmlFor="revision-note">Motivo / procedencia de la corrección</label><textarea id="revision-note" value={revisionNote} onChange={e => setRevisionNote(e.target.value)} /><p className="note">Se conservan los metadatos originales; indica cualquier cambio de sujeto, precisión o base en la corrección.</p><div className="review-actions"><button className="review-save">Guardar corrección</button><button type="button" onClick={() => setEditing(false)}>Cancelar</button></div></form> : <div className="review-actions"><button className="review-confirm" onClick={() => review(key, c, 'confirm')}>Confirmar dato</button><button onClick={() => setEditing(true)}>Corregir</button><button className="review-danger" onClick={() => review(key, c, 'discard')}>Descartar</button>{decision && <button onClick={() => review(key, c, 'restore')}>Restaurar candidato</button>}</div>}<p className="review-warnings">La revisión es operativa; no verifica documentos ni aprueba financiación.</p></div>}</>; })()}</div>) : <p>Sin informar</p>}</div>)}</div></>}</div><div className="result-footer"><span>Preparación manual · sin conexión CRM</span></div>{result && <div className="result-content"><div className="section-title"><h3>Vista previa CRM</h3><small>Carga manual</small></div>{preview ? <><textarea className="editor" aria-label="Vista previa de ficha CRM" readOnly value={preview} /><button className="primary" disabled={blockers.length > 0} onClick={copyPreview}>Copiar ficha CRM</button>{blockers.includes('empty') && <p role="alert">No hay datos utilizables. Revisa la conversación y las incidencias, y vuelve a analizar si es necesario. <button className="micro" onClick={() => { setView('reading'); document.getElementById('conversation-panel')?.scrollIntoView(); }}>Revisar conversación</button></p>}{blockers.includes('conflict') && <p role="alert">Hay conflictos pendientes. Revisa y resuelve los campos antes de copiar la ficha actual. <button className="micro" onClick={() => document.getElementById('facts-panel')?.scrollIntoView()}>Revisar ficha</button></p>}{blockers.includes('stage') && <p role="alert">La etapa anterior ya no refleja el expediente. Confirma la etapa sugerida antes de copiar.</p>}<p role="status">{blockers.length ? '' : copyStatus}</p></> : <p>Reanaliza antes de preparar una ficha actual.</p>}</div>}</section></div></main><div className="disclaimer">Solo datos ficticios · Las declaraciones y revisiones no constituyen verificación documental ni aprobación financiera.</div>
  </>;
}

:root {
  --ink:#24302e; --ink-2:#52605c; --muted:#7b8883; --paper:#f8f7f3; --white:#fff;
  --line:#e6e7e1; --soft:#f2f3ee; --coral:#de634e; --coral-dark:#a93a2e;
  --coral-soft:#fff0eb; --green:#347c62; --green-soft:#e8f4ee;
  --amber:#9f712a; --amber-soft:#fff5df; --slate-soft:#edf1ef;
  --shadow:0 12px 35px rgba(25,46,38,.045); --radius:16px;
}
* { box-sizing:border-box; }
html { scroll-behavior:smooth; }
body { margin:0; background:var(--paper); color:var(--ink); font:14px/1.48 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
button, textarea, input { font:inherit; }
button { cursor:pointer; }
button:disabled { cursor:not-allowed; opacity:.55; }
:focus-visible { outline:3px solid rgba(222,99,78,.45); outline-offset:3px; }
.designbar { background:#283a34; color:#e5f0ea; padding:9px 32px; display:flex; align-items:center; justify-content:space-between; gap:20px; flex-wrap:wrap; font-size:12px; }
.designbar strong { color:#fff; }
.designbar .state-controls { display:flex; gap:6px; align-items:center; flex-wrap:wrap; }
.designbar button { border:1px solid #5b7066; color:#e5f0ea; background:transparent; border-radius:7px; padding:5px 9px; font-size:11px; }
.designbar button.active { color:#283a34; background:#e9f4eb; border-color:#e9f4eb; }
.app-top { background:var(--white); border-bottom:1px solid var(--line); }
.app-top .inner { max-width:1520px; padding:20px 34px; margin:auto; display:flex; justify-content:space-between; align-items:center; gap:22px; }
.logo { letter-spacing:-1.7px; font-size:30px; line-height:1; font-weight:850; white-space:nowrap; }
.logo span { color:var(--coral); }
.logo em { font-size:12px; letter-spacing:0; font-weight:650; font-style:normal; margin-left:14px; color:var(--muted); vertical-align:middle; }
.top-badges { display:flex; align-items:center; gap:10px; flex-wrap:wrap; justify-content:flex-end; }
.tiny-pill { background:var(--soft); color:var(--ink-2); border:1px solid var(--line); border-radius:999px; padding:5px 11px; font-size:11px; font-weight:650; }
.tiny-pill.demo { background:#fef4e6; color:#92642a; border-color:#f8e0bd; }
main { max-width:1520px; margin:auto; padding:28px 34px 42px; }
.headline { display:flex; align-items:flex-end; justify-content:space-between; gap:22px; margin-bottom:22px; }
.eyebrow { color:var(--coral-dark); font-size:11px; font-weight:800; letter-spacing:1.4px; text-transform:uppercase; margin:0 0 7px; }
h1 { font-size:clamp(25px,2.3vw,34px); line-height:1.16; letter-spacing:-1.05px; margin:0 0 7px; font-weight:760; }
.subtitle { color:var(--ink-2); margin:0; max-width:770px; }
.link-btn { color:var(--ink-2); background:transparent; border:1px solid var(--line); border-radius:10px; padding:9px 13px; white-space:nowrap; font-size:12px; font-weight:650; }
.link-btn:hover { background:var(--soft); }
.workspace { display:grid; grid-template-columns:minmax(340px, 44fr) minmax(500px, 56fr); gap:18px; align-items:start; }
.surface { background:var(--white); border:1px solid var(--line); border-radius:var(--radius); box-shadow:var(--shadow); min-width:0; }
.surface-header { padding:20px 22px; display:flex; align-items:center; justify-content:space-between; gap:16px; border-bottom:1px solid var(--line); }
.surface-header h2 { margin:0; font-size:17px; letter-spacing:-.35px; }
.surface-header p { margin:3px 0 0; color:var(--muted); font-size:12px; }
.source-head { padding:22px; }
.field-label { text-transform:uppercase; font-size:10px; font-weight:800; letter-spacing:.95px; color:var(--muted); display:block; margin-bottom:7px; }
.case-row { display:flex; gap:10px; align-items:center; margin-bottom:16px; }
.alias { flex:1; min-width:0; padding:11px 12px; border:1px solid var(--line); border-radius:10px; background:#fff; color:var(--ink); }
.case-chip { background:var(--amber-soft); color:#866322; border-radius:99px; padding:8px 11px; font-size:11px; font-weight:750; white-space:nowrap; }
.example-head { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:7px; }
.examples { display:flex; gap:7px; flex-wrap:wrap; margin-bottom:16px; }
.example-btn { background:var(--white); border:1px solid var(--line); padding:8px 13px; border-radius:10px; font-size:12px; color:var(--ink-2); font-weight:650; }
.example-btn.active { background:var(--coral-soft); border-color:#eac3b9; color:var(--coral-dark); }
.tabs { display:flex; gap:18px; border-bottom:1px solid var(--line); padding:0 22px; }
.tab { padding:12px 2px 12px; border:0; border-bottom:2px solid transparent; background:transparent; color:var(--muted); font-size:12px; font-weight:750; }
.tab.active { color:var(--ink); border-color:var(--coral); }
.conversation-body { padding:17px 18px 18px; min-height:385px; max-height:535px; overflow:auto; }
.chat-row { display:flex; margin:0 0 16px; gap:9px; align-items:flex-start; scroll-margin-top:15px; border-radius:10px; }
.chat-row.advisor { flex-direction:row-reverse; }
.msg-avatar { width:29px; height:29px; border-radius:10px; background:#e8ede8; color:var(--green); display:grid; place-items:center; font-size:11px; font-weight:800; flex:none; }
.chat-row.advisor .msg-avatar { background:var(--coral-soft); color:var(--coral-dark); }
.chat-inner { max-width:86%; min-width:0; }
.msg-meta { font-size:10px; color:var(--muted); font-weight:700; margin-bottom:4px; }
.chat-row.advisor .msg-meta { text-align:right; }
.bubble { background:var(--soft); padding:12px 14px; border-radius:3px 13px 13px 13px; color:#34413c; white-space:pre-wrap; font-size:12.5px; line-height:1.6; border:1px solid transparent; }
.chat-row.advisor .bubble { background:#fff2ed; border-radius:13px 3px 13px 13px; }
.chat-row.unknown .bubble { background:#fff8e9; }
.chat-row.highlight .bubble { outline:2px solid var(--coral); outline-offset:2px; background:#fff7ed; }
.editor-wrap { display:none; height:100%; min-height:385px; }
.editor-wrap.active { display:flex; flex-direction:column; }
.editor { width:100%; resize:vertical; min-height:330px; flex:1; padding:14px; background:#fbfbf9; border:1px solid var(--line); border-radius:10px; color:var(--ink); font-size:12.5px; line-height:1.75; }
.editor-help { margin:10px 0 0; font-size:11px; color:var(--muted); }
.source-footer { border-top:1px solid var(--line); padding:17px 22px; background:#fdfdfb; border-radius:0 0 16px 16px; }
.source-action { display:flex; gap:9px; align-items:center; }
.primary { border:1px solid var(--coral); background:var(--coral); color:#fff; border-radius:11px; padding:12px 18px; font-weight:750; letter-spacing:-.1px; }
.primary:hover:not(:disabled) { background:var(--coral-dark); border-color:var(--coral-dark); }
.secondary { border:1px solid var(--line); color:var(--ink); background:#fff; border-radius:10px; padding:11px 13px; font-weight:700; }
.secondary:hover { background:var(--soft); }
.tiny-note { margin:9px 0 0; color:var(--muted); font-size:11px; }
.result-head { display:flex; justify-content:space-between; gap:15px; align-items:center; padding:20px 22px 18px; border-bottom:1px solid var(--line); }
.result-head h2 { font-size:17px; margin:0; letter-spacing:-.4px; }
.result-head p { font-size:12px; color:var(--muted); margin:3px 0 0; }
.result-content { padding:21px 22px 25px; }
.state-overview { border:1px solid #edd9b5; background:#fffbf0; border-radius:12px; padding:16px; display:flex; gap:11px; margin-bottom:20px; }
.state-icon { width:33px; height:33px; border-radius:10px; background:#ffedc8; color:#9f712a; font-weight:800; font-size:17px; display:grid; place-items:center; flex:none; }
.state-overview h3 { margin:0 0 4px; font-size:14px; }
.state-overview p { margin:0; font-size:12px; line-height:1.55; color:#695a43; }
.section-title { display:flex; align-items:baseline; justify-content:space-between; gap:12px; margin:0 0 10px; }
.section-title h3 { font-size:13px; font-weight:800; margin:0; letter-spacing:-.1px; }
.section-title small { font-size:11px; color:var(--muted); }
.facts { display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-bottom:20px; }
.fact { border:1px solid var(--line); border-radius:11px; padding:11px 12px; min-width:0; }
.fact-title { font-size:10px; color:var(--ink-2); font-weight:700; margin-bottom:5px; }
.fact-value { font-size:14px; font-weight:760; letter-spacing:-.28px; overflow-wrap:anywhere; }
.fact-note { display:flex; gap:5px; flex-wrap:wrap; align-items:center; color:var(--muted); font-size:10px; margin-top:6px; }
.fact.wide { grid-column:span 2; }
.chip { font-size:10px; padding:2px 7px; border-radius:99px; font-weight:740; background:var(--slate-soft); color:var(--ink-2); white-space:nowrap; }
.chip.unknown { background:#f2f2f2; color:#7a817b; }
.chip.warn { background:var(--amber-soft); color:#946724; }
.chip.good { background:var(--green-soft); color:var(--green); }
.evidence { border:0; background:none; color:var(--coral-dark); text-decoration:underline; text-underline-offset:2px; padding:0; font-size:10px; font-weight:750; }
.issue { display:flex; gap:11px; background:var(--coral-soft); border:1px solid #f6d5ca; border-radius:12px; padding:14px 15px; margin-bottom:19px; }
.issue .marker { color:var(--coral-dark); font-weight:850; font-size:16px; }
.issue strong { display:block; font-size:12px; margin-bottom:4px; }
.issue p { color:#86594d; margin:0; font-size:11.5px; }
.issue .evidence { font-size:11px; margin-top:4px; }
.question { border:1px solid var(--line); border-radius:12px; padding:15px; }
.question .question-head { display:flex; justify-content:space-between; gap:12px; margin-bottom:9px; }
.question-head strong { font-size:13px; }
.question textarea { border:1px solid var(--line); background:#fbfcf9; border-radius:9px; width:100%; padding:11px; resize:vertical; min-height:76px; line-height:1.65; color:var(--ink); font-size:12px; }
.question-bottom { display:flex; align-items:center; justify-content:space-between; gap:14px; margin-top:10px; }
.question-bottom small { color:var(--muted); font-size:11px; }
.micro { padding:8px 12px; font-size:11px; border:1px solid var(--line); border-radius:9px; background:#fff; font-weight:800; white-space:nowrap; }
.micro:hover { background:var(--soft); }
.result-footer { border-top:1px solid var(--line); padding:16px 22px; display:flex; align-items:center; justify-content:space-between; gap:14px; }
.footer-muted { color:var(--muted); font-size:11px; max-width:280px; }
.foot-btn { white-space:nowrap; border:1px solid var(--line); background:var(--soft); color:var(--muted); border-radius:10px; padding:10px 13px; font-size:12px; font-weight:750; }
.empty-illustration { text-align:center; padding:58px 22px 65px; }
.empty-icon { width:63px; height:63px; border-radius:19px; margin:0 auto 16px; display:grid; place-items:center; background:var(--soft); color:var(--green); font-size:25px; }
.empty-illustration h3 { margin:0 0 8px; font-size:19px; letter-spacing:-.35px; }
.empty-illustration p { max-width:350px; margin:0 auto; color:var(--ink-2); font-size:12px; line-height:1.65; }
.loadingdots { display:flex; justify-content:center; gap:7px; margin-top:18px; }
.loadingdots span { width:7px; height:7px; border-radius:100%; background:var(--coral); animation:pulse 1s infinite ease-in-out; }
.loadingdots span:nth-child(2) { animation-delay:.15s; }.loadingdots span:nth-child(3) { animation-delay:.3s; }
@keyframes pulse { 0%,65%,100% { opacity:.25; transform:scale(.75); } 32% { opacity:1; transform:scale(1.12); } }
.stale-banner { background:var(--amber-soft); border:1px solid #ecd9af; color:#795b25; border-radius:11px; padding:12px 14px; margin-bottom:14px; font-size:12px; font-weight:700; }
.result-stale { opacity:.64; }
.error-box { background:#fff1ee; color:#933d30; border:1px solid #f1c8c1; border-radius:12px; padding:14px; margin-bottom:17px; font-size:12px; }
.disclaimer { max-width:1520px; margin:10px auto 35px; padding:0 34px; color:var(--muted); font-size:11px; display:flex; justify-content:space-between; gap:18px; flex-wrap:wrap; }
#toast { position:fixed; bottom:22px; right:22px; background:#263f34; color:#fff; border-radius:10px; padding:12px 16px; box-shadow:0 12px 30px #28382d22; font-size:12px; opacity:0; transform:translateY(8px); transition:.2s ease; pointer-events:none; z-index:3; }
#toast.show { opacity:1; transform:translateY(0); }
@media (max-width:1080px) { .workspace { grid-template-columns:1fr; } .conversation-body { max-height:420px; min-height:280px; } .headline { align-items:flex-start; } }
@media (max-width:650px) { .designbar { padding:9px 15px; } .app-top .inner { padding:17px; } main { padding:22px 15px; } .headline { flex-direction:column; align-items:flex-start; } .surface-header,.source-head,.result-content,.result-head { padding:17px; } .surface-header { flex-wrap:wrap; } .tabs { padding:0 17px; } .result-footer { padding:14px 17px; } .facts { grid-template-columns:1fr; } .fact.wide { grid-column:span 1; } .top-badges { display:none; } .disclaimer { padding:0 15px; } .source-action { flex-wrap:wrap; } }

/* UX1 v0.2: lectura por prioridad, sin convertir la interfaz en un formulario paso a paso. */
.top-badges .stage-top { background:var(--amber-soft); border-color:#f3dfae; color:#87611b; }
.source-meta { color:var(--muted); font-size:11px; font-weight:650; white-space:nowrap; }
.source-head { padding-bottom:15px; }
.result-content { padding-top:18px; }
.state-overview { align-items:flex-start; background:#f5f8f4; border-color:#dfeae0; margin-bottom:17px; padding:14px 16px; }
.state-overview .state-icon { background:#e4f0e8; color:#37765a; }
.state-overview h3 { font-size:14px; }
.state-overview p { color:#4f675b; }
.overview-metrics { display:flex; align-items:center; flex-wrap:wrap; gap:6px; margin-top:8px; }
.metric-pill { background:#fff; border:1px solid #dfe7dd; border-radius:99px; font-size:10px; font-weight:730; color:#50655b; padding:3px 8px; }
.metric-pill.warn { color:#926826; border-color:#f3e0b4; background:#fff8e6; }
.focus-title { margin:0 0 10px; display:flex; justify-content:space-between; gap:12px; align-items:baseline; }
.focus-title h3 { margin:0; font-size:13px; letter-spacing:-.1px; }
.focus-title small { color:var(--muted); font-size:10px; }
.priority-grid { display:grid; grid-template-columns:minmax(0, 1fr) minmax(0, 1.15fr); gap:10px; margin-bottom:11px; align-items:stretch; }
.key-issue { border-radius:12px; padding:14px 15px; background:var(--coral-soft); border:1px solid #f6d5ca; min-width:0; }
.key-issue-label { color:var(--coral-dark); display:flex; gap:7px; align-items:center; font-size:10px; letter-spacing:.6px; font-weight:850; text-transform:uppercase; margin-bottom:8px; }
.key-issue h4 { margin:0 0 7px; font-size:13px; letter-spacing:-.15px; }
.key-issue p { color:#805c52; margin:0 0 8px; font-size:11px; line-height:1.55; }
.key-issue .evidence { font-size:11px; }
.priority-grid .question { padding:13px; margin:0; min-width:0; }
.priority-grid .question-head { margin-bottom:7px; }
.priority-grid .question-head strong { font-size:11px; }
.priority-grid .question textarea { min-height:93px; font-size:11.5px; }
.priority-grid .question-bottom { gap:9px; flex-wrap:wrap; }
.priority-grid .question-bottom small { font-size:10px; flex:1; min-width:170px; }
.pending-inline { border:1px solid var(--line); background:#fdfdfa; border-radius:10px; padding:10px 12px; font-size:11px; color:var(--ink-2); margin:0 0 19px; }
.pending-inline strong { color:var(--ink); }
.pending-inline b { color:var(--amber); }
.facts { margin-bottom:12px; }
.fact { transition:border-color .15s; }
.fact:hover { border-color:#cdd9d0; }
.facts-help { font-size:11px; color:var(--muted); line-height:1.55; margin:0; }
